 wasteConnectionLock($pdo,$id,function()use($pdo,$admin,$id,$a,$enabled,$legacy,$times,$version){$old=wasteConnection($pdo,$id);$changed=!$old||$old['address_json']!==json_encode($a,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR)||$old['address_hash']!==hash('sha256',$legacy);$pdo->beginTransaction();try{$q=$pdo->prepare('SELECT * FROM properties WHERE id=? FOR UPDATE');$q->execute([$id]);$property=$q->fetch();if($version!==null&&(int)$property['row_version']!==$version)throw new RuntimeException('Objekt inzwischen geändert. Neu laden und Adresse prüfen.');if($property['address']!==$legacy){$pdo->prepare('UPDATE properties SET address=?,row_version=row_version+1 WHERE id=?')->execute([$legacy,$id]);require_once __DIR__.'/operations.php';opsEvent($pdo,$admin,'property',$id,'updated',$property,['address'=>$legacy]);}$pdo->prepare("INSERT INTO waste_connections(property_id,enabled,address_json,address_hash,selection_json,offered_json,bins_json,out_time,in_time) VALUES(?,?,?,?, '[]','[]','[]',?,?) ON DUPLICATE KEY UPDATE enabled=VALUES(enabled),address_json=VALUES(address_json),address_hash=VALUES(address_hash),out_time=VALUES(out_time),in_time=VALUES(in_time),status=IF(VALUES(enabled)=0,'disabled',IF(?, 'confirmation',status)),selection_json=IF(?,'[]',selection_json),offered_json=IF(?,'[]',offered_json),bins_json=IF(?,'[]',bins_json),pending_token=NULL")->execute([$id,$enabled,json_encode($a,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),hash('sha256',$legacy),...$times,$changed?1:0,$changed?1:0,$changed?1:0,$changed?1:0]);wasteHistory($pdo,$admin,'connection_config',['property'=>$id,'enabled'=>$enabled,'address_changed'=>$changed,'old_tasks_preserved'=>true]);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}});
}
function wasteDiscover(PDO $pdo,int $admin,int $id,?string $choice=null,?GszWasteProvider $provider=null):array {
 return wasteConnectionLock($pdo,$id,function()use($pdo,$admin,$id,$choice,$provider){$c=wasteConnection($pdo,$id);if(!$c||!$c['enabled'])throw new RuntimeException('Mülltonnenservice zuerst aktivieren.');if(!hash_equals($c['address_hash'],hash('sha256',$c['current_address'])))throw new RuntimeException('Objektadresse geändert. Adresse und Leistungsumfang neu bestätigen.');
  $pdo->prepare('UPDATE waste_connections SET last_attempt_at=UTC_TIMESTAMP() WHERE property_id=?')->execute([$id]);try{$address=json_decode($c['address_json'],true,32,JSON_THROW_ON_ERROR);$providerKey=wasteProviderRegistry()[wasteAddressKey($address['city'])]['provider']??'regioit_krwaf';$result=($provider??wasteProvider($pdo,$providerKey))->discover($address,$choice);$pdo->prepare('UPDATE waste_connections SET provider_key=?,status=?,selection_json=?,offered_json=?,error_code=?,pending_token=NULL WHERE property_id=?')->execute([isset($result['selection'])?$providerKey:'',$result['status'],json_encode($result,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),json_encode($result['offered']??[],JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),'',$id]);wasteHistory($pdo,$admin,'connection_discovery',['property'=>$id,'status'=>$result['status'],'matched'=>isset($result['selection'])]);return $result;}
  catch(Throwable $e){$pdo->prepare("UPDATE waste_connections SET status='failed',error_code='GSZ_WASTE_SOURCE_FAILED',next_sync_at=UTC_TIMESTAMP()+INTERVAL 6 HOUR WHERE property_id=?")->execute([$id]);return ['status'=>'failed','message'=>'Offizielle Datenquelle nicht erreichbar, leer oder Format geändert. Bestätigte Altdaten bleiben erhalten.'];}
 });
}
function wasteChooseBins(PDO $pdo,int $admin,int $id,array $ids):void {
 wasteConnectionLock($pdo,$id,function()use($pdo,$admin,$id,$ids){$c=wasteConnection($pdo,$id);if(!$c||!$c['enabled']||!hash_equals($c['address_hash'],hash('sha256',$c['current_address'])))throw new RuntimeException('Aktive, bestätigte Objektadresse erforderlich.');$s=json_decode($c['selection_json'],true,32,JSON_THROW_ON_ERROR);if(empty($s['selection']))throw new RuntimeException('Zuerst Straße und Quelle zuordnen.');if(!$ids||count($ids)>12||count(array_unique($ids))!==count($ids))throw new RuntimeException('1–12 betreute Behältervarianten auswählen.');$offered=json_decode($c['offered_json'],true,32,JSON_THROW_ON_ERROR);$bins=[];foreach($ids as $idValue){$found=null;foreach($offered as $b)if((string)$b['id']===(string)$idValue)$found=$b;if(!$found)throw new RuntimeException('Unbekannte oder nicht angebotene Tonnenart.');$bins[]=$found;}
 usort($bins,fn($a,$b)=>$a['id']<=>$b['id']);$pdo->prepare("UPDATE waste_connections SET bins_json=?,status='confirmation',pending_token=NULL,next_sync_at=NULL WHERE property_id=?")->execute([json_encode($bins,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),$id]);wasteHistory($pdo,$admin,'connection_bins',['property'=>$id,'provider_ids'=>array_column($bins,'id'),'old_tasks_preserved'=>true]);});
}
function wasteAutoPreview(PDO $pdo,int $admin,array $c,GszWasteProvider $provider):array {
 $selection=json_decode($c['selection_json'],true,32,JSON_THROW_ON_ERROR)['selection']??null;$bins=json_decode($c['bins_json'],true,32,JSON_THROW_ON_ERROR);if(!$selection||!$bins)throw new RuntimeException('Adress- und Tonnenauswahl erforderlich.');$rows=$provider->calendar($selection,$bins);if(!$rows)throw new RuntimeException('Kalender enthält keine künftigen Leerungen.');$mapping=[];foreach($bins as $b)$mapping[$b['name']]=$b['canonical'];$today=(new DateTimeImmutable('today',new DateTimeZone('Europe/Berlin')))->format('Y-m-d');$until=max(array_column($rows,'date'));
 // Separate provenance on changed address/bin scope, never mutate old source address or archive identities.
 $name='Abfallnavi automatisch '.substr(hash('sha256',json_encode([$c['address_hash'],$selection['street']['staticId'],$selection['house']['staticId']??null,$bins])),0,20);
 $pdo->prepare('INSERT INTO waste_sources(property_id,name,address,source_date,valid_until,auto_managed) VALUES(?,?,?,?,?,1) ON DUPLICATE KEY UPDATE valid_until=GREATEST(valid_until,VALUES(valid_until))')->execute([$c['property_id'],$name,$c['current_address'],$today,$until]);$q=$pdo->prepare('SELECT id FROM waste_sources WHERE property_id=? AND name=?');$q->execute([$c['property_id'],$name]);$source=(int)$q->fetchColumn();$pdo->prepare('UPDATE waste_connections SET source_id=? WHERE property_id=?')->execute([$source,$c['property_id']]);
 $preview=wastePreview($pdo,$source,$rows,$mapping,[$today,planDate($today,550)]);$token=bin2hex(random_bytes(32));$pdo->prepare('INSERT INTO waste_imports(token,admin_id,source_id,file_hash,fingerprint,payload) VALUES(?,?,?,?,?,?)')->execute([$token,$admin,$source,hash('sha256',json_encode($rows,JSON_THROW_ON_ERROR)),wasteSnapshot($pdo),json_encode($preview,JSON_THROW_ON_ERROR)]);$pdo->prepare("UPDATE waste_connections SET pending_token=?,status='confirmation',last_attempt_at=UTC_TIMESTAMP(),next_sync_at=UTC_TIMESTAMP()+INTERVAL 1 DAY,error_code='' WHERE property_id=?")->execute([$token,$c['property_id']]);return ['token'=>$token,'source_id'=>$source,'conflicts'=>$preview['conflicts'],'rows'=>count($rows)];
}
function wasteConfirmConnection(PDO $pdo,int $admin,int $id,string $token,bool $ackRules=false):void {
 wasteConnectionLock($pdo,$id,function()use($pdo,$admin,$id,$token,$ackRules){$c=wasteConnection($pdo,$id);if(!$c||!$c['enabled']||!hash_equals($c['address_hash'],hash('sha256',$c['current_address'])))throw new RuntimeException('Adresse/Service geändert. Neu prüfen.');$q=$pdo->prepare('SELECT * FROM waste_imports WHERE token=? AND admin_id=? AND source_id=?');$q->execute([$token,$admin,$c['source_id']]);$i=$q->fetch();if(!$i)throw new RuntimeException('Vorschau nicht vorhanden.');if($i['applied_at'])return;if($c['pending_token']!==$token)throw new RuntimeException('Vorschau wurde ersetzt.');
